def _cubic(q):
    from itertools import combinations_with_replacement
    terms = [np.prod(q[:, idx], axis=1) for d in (1, 2, 3) for idx in combinations_with_replacement(range(q.shape[1]), d)]
    return np.column_stack([np.ones(len(q)), *terms])
